#include <stdio.h>

int main(void) {
    int apples = 3;
    int oranges = 4;
    printf("Total: %d\n", apples + oranges);
    return 0;
}

#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 3; i++) {
        printf("%d\n", i);
    }
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string name = "Ada";
    std::cout << "Hello, " << name << "!\n";
    return 0;
}

#include <iostream>

int main() {
    for (int number = 1; number <= 3; ++number) {
        std::cout << number << '\n';
    }
    return 0;
}
